import{_ as r,o as t,c as a,a5 as s}from"./chunks/framework.QWVCgkrI.js";const o="/study/images/browser/wasm-module-to-instance.svg",i="/study/images/browser/wasm-linear-memory-layout.svg",y=JSON.parse('{"title":"WebAssemblyと線形メモリ — バイナリから実行・共有するバイト列まで","description":"","frontmatter":{"title":"WebAssemblyと線形メモリ — バイナリから実行・共有するバイト列まで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"Wasmのバイナリと実行時の状態を分け、JavaScriptとWasmが線形メモリを読み書きする仕組み、拡張と境界検査を説明する。","aliases":["WebAssembly","Wasm","WAT","線形メモリ","linear memory","memory32","instantiate","instantiateStreaming","imports","exports","LEB128","i32.load","i32.store","memory.grow","trap"],"verification":"WebAssembly Core・JavaScript Interface・Web API、V8・Emscripten・rustcの公式資料と照合（2026-11-05）"}},"headers":[],"relativePath":"browser/webassembly-linear-memory.md","filePath":"browser/webassembly-linear-memory.md"}'),n={name:"browser/webassembly-linear-memory.md"};function l(c,e,d,m,b,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="webassemblyと線形メモリ-—-バイナリから実行・共有するバイト列まで" tabindex="-1">WebAssemblyと線形メモリ — バイナリから実行・共有するバイト列まで <a class="header-anchor" href="#webassemblyと線形メモリ-—-バイナリから実行・共有するバイト列まで" aria-label="Permalink to &quot;WebAssemblyと線形メモリ — バイナリから実行・共有するバイト列まで&quot;">​</a></h1><p><strong>WebAssembly（Wasm）</strong> は、ブラウザなどの実行環境が検証して動かせる命令形式です。ブラウザでは、JavaScriptがWasmのモジュールを読み込み、外部へ公開された関数を呼びます。関数に配列などを渡すときは、<strong>線形メモリ</strong>上にデータを並べ、どの位置から何バイト使うかを双方で決める方法があります。<a href="https://webassembly.github.io/spec/core/intro/introduction.html" target="_blank" rel="noreferrer">WebAssembly Coreの概要</a>、<a href="https://webassembly.github.io/spec/js-api/" target="_blank" rel="noreferrer">WebAssembly JavaScript Interface</a></p><h2 id="wasmの先頭とセクションを読む" tabindex="-1">.wasmの先頭とセクションを読む <a class="header-anchor" href="#wasmの先頭とセクションを読む" aria-label="Permalink to &quot;.wasmの先頭とセクションを読む&quot;">​</a></h2><p><code>.wasm</code> はモジュールのバイナリ表現です。実践のファイルでは、先頭4バイトの <code>00 61 73 6d</code> が形式を見分けるマジック番号、その次の <code>01 00 00 00</code> がバイナリ形式の版を表します。この後に、型、インポート、関数、メモリ、エクスポート、命令本体などの<strong>セクション</strong>が続きます。各セクションには種別を表すIDと内容のバイト数があり、バイト数は符号なしの<strong>LEB128</strong>という可変長形式で表します。<a href="https://webassembly.github.io/spec/core/binary/modules.html#binary-module" target="_blank" rel="noreferrer">WebAssembly Coreのバイナリモジュール</a>、<a href="https://webassembly.github.io/spec/core/binary/modules.html#binary-section" target="_blank" rel="noreferrer">セクションの形式</a>、<a href="https://webassembly.github.io/spec/core/binary/values.html#integers" target="_blank" rel="noreferrer">整数のエンコード</a></p><p><strong>WAT</strong>（WebAssembly Text Format）は、同じモジュールの構造を人が読める形で表したものです。たとえば <code>(memory (export &quot;memory&quot;) 1 2)</code> は、初期1ページ・最大2ページのメモリを定義し、外から <code>memory</code> という名前で参照できるようにします。ブラウザのWebAssembly APIへは、WATをツールで変換したバイナリを渡します。<a href="https://webassembly.github.io/spec/core/text/index.html" target="_blank" rel="noreferrer">WebAssembly Coreのテキスト形式</a></p><h2 id="検証・コンパイル・インスタンス化を分ける" tabindex="-1">検証・コンパイル・インスタンス化を分ける <a class="header-anchor" href="#検証・コンパイル・インスタンス化を分ける" aria-label="Permalink to &quot;検証・コンパイル・インスタンス化を分ける&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段階</th><th>ブラウザで起きること</th></tr></thead><tbody><tr><td>取得</td><td>HTTP応答からモジュールのバイト列を受け取る</td></tr><tr><td>検証</td><td>モジュールを解釈し、命令が使う型や関数の参照先が規則に合うかを調べる</td></tr><tr><td>コンパイル</td><td>実行に使える形を準備し、JavaScriptには <code>WebAssembly.Module</code> を返す</td></tr><tr><td>インスタンス化</td><td>インポートを実際の関数やメモリなどに結び付け、モジュール内で定義したメモリなどを作る</td></tr><tr><td>呼び出し</td><td><code>WebAssembly.Instance</code> の <code>exports</code> にある関数を呼び、必要に応じてメモリを読み書きする</td></tr></tbody></table><p>インスタンス化では、データセグメントを使って初期化し、開始関数の宣言があれば実行します。同じ <code>Module</code> から複数の <code>Instance</code> を作れます。メモリを独自に定義したインスタンスはそれぞれ別のメモリを使い、同じメモリをインポートしたインスタンスはそのメモリを使います。エンジンの内部では、呼び出し時に関数をコンパイルしたり、頻繁に使う関数を後から最適化したりする構成もあります。<a href="https://webassembly.github.io/spec/core/exec/modules.html" target="_blank" rel="noreferrer">WebAssembly Coreのインスタンス化</a>、<a href="https://webassembly.github.io/spec/js-api/" target="_blank" rel="noreferrer">JavaScript InterfaceのModuleとInstance</a>、<a href="https://v8.dev/docs/wasm-compilation-pipeline" target="_blank" rel="noreferrer">V8のコンパイル実装例</a></p><p>JavaScriptでは、<code>compile()</code> でモジュールを用意してから、<code>instantiate()</code> でインスタンスを作る段階を分けられます。次の <code>bytes</code> は取得済みのバイト列、<code>imports</code> はモジュールに渡す値を名前でまとめたオブジェクトです。<a href="https://webassembly.github.io/spec/js-api/" target="_blank" rel="noreferrer">WebAssembly JavaScript Interfaceのコンパイルとインスタンス化</a></p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebAssembly.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bytes)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> instance</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebAssembly.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">instantiate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, imports)</span></span></code></pre></div><figure class="study-figure"><img src="`+o+'" alt="先頭8バイトとセクション列を持つWasmバイナリを読み込む。検証とコンパイルでModuleを用意し、インポートの結び付けと初期化でInstanceを作る。JavaScriptが公開された関数を呼び、エクスポートされたメモリを使う。" width="760" height="1060" loading="lazy"><figcaption>モジュールの定義を読み込む段階と、値を保持するインスタンスを用意する段階を分けて見ます。<a href="/study/images/browser/wasm-module-to-instance.svg" target="_blank" rel="noopener noreferrer">モジュールからインスタンスまでの図を拡大</a></figcaption></figure><p><code>WebAssembly.instantiateStreaming(fetch(url), imports)</code> では、HTTP応答の受信とコンパイルを並行して進められます。検証を通ったモジュールからインスタンスを作ります。成功を表すHTTPステータスと、パラメータのない <code>Content-Type: application/wasm</code> が必要です。別オリジンの応答ならCORSの条件も満たします。応答を <code>arrayBuffer()</code> で受け取ってから <code>WebAssembly.instantiate()</code> に渡す経路もあります。<a href="https://webassembly.github.io/spec/web-api/#streaming-modules" target="_blank" rel="noreferrer">WebAssembly Web APIのストリーミング</a>、<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a></p><table tabindex="0"><thead><tr><th>エラー</th><th>どこで起きるかの例</th></tr></thead><tbody><tr><td><code>WebAssembly.CompileError</code></td><td>バイナリを解釈できない、あるいはモジュールが検証規則に合わない</td></tr><tr><td><code>WebAssembly.LinkError</code></td><td>インスタンス化時に、指定されたインポートの値が要求される種類や型に合わない</td></tr><tr><td><code>WebAssembly.RuntimeError</code></td><td>実行中にトラップした。線形メモリの範囲外を読む例など</td></tr></tbody></table><p>通信や応答の条件に関わる失敗と、Wasmの検証・実行に関わる失敗を分けると、調べる箇所を絞れます。たとえばストリーミング時のMIME型の不一致は <code>TypeError</code> です。開始関数がトラップすれば、インスタンスを作る途中でも <code>RuntimeError</code> が起きます。<a href="https://webassembly.github.io/spec/js-api/#error-objects" target="_blank" rel="noreferrer">WebAssembly JavaScript Interfaceのエラー型</a>、<a href="https://webassembly.github.io/spec/web-api/#streaming-modules" target="_blank" rel="noreferrer">WebAssembly Web APIのストリーミング</a></p><h2 id="線形メモリはバイトオフセットで読む" tabindex="-1">線形メモリはバイトオフセットで読む <a class="header-anchor" href="#線形メモリはバイトオフセットで読む" aria-label="Permalink to &quot;線形メモリはバイトオフセットで読む&quot;">​</a></h2><p><strong>線形メモリ</strong>は、先頭を0とする連続したバイト列です。実践で使う <code>memory32</code> では、<code>i32.load</code> や <code>i32.store</code> が32ビットのアドレス値を受け取り、線形メモリの中で位置を求めます。たとえば <code>add_at(16, 1)</code> の <code>16</code> は先頭から16バイト進んだ位置です。OS上のプロセスやJavaScriptオブジェクトの位置とは別のアドレス空間です。Wasmの関数が使う局所変数やオペランドスタックも、仕様では線形メモリと区別されます。C/C++のツールチェーンが線形メモリ上に置くスタックは、ツールチェーンが設ける領域です。<a href="https://webassembly.github.io/spec/core/exec/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのメモリ命令</a>、<a href="https://webassembly.github.io/spec/core/exec/runtime.html" target="_blank" rel="noreferrer">実行時の状態</a>、<a href="https://emscripten.org/docs/tools_reference/settings_reference.html#stack-size" target="_blank" rel="noreferrer">EmscriptenのSTACK_SIZE</a></p><p>実践では、JavaScriptが <code>memory.buffer</code> に対して <code>DataView</code> を作り、<code>setInt32(16, 41, true)</code> で値を書きます。最後の <code>true</code> はリトルエンディアンの指定です。Wasmの <code>i32.load</code> と <code>i32.store</code> もリトルエンディアンで4バイトを扱います。Wasm関数が1を加えると、同じオフセット16〜19の4バイトは <code>29 00 00 00</code> から <code>2a 00 00 00</code> に変わり、JavaScriptからは42と読めます。<a href="https://webassembly.github.io/spec/core/exec/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのメモリ命令</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-dataview.prototype.setint32" target="_blank" rel="noreferrer">ECMAScriptのDataView.setInt32</a></p><figure class="study-figure"><img src="'+i+'" alt="1ページの線形メモリのオフセット16から19にJavaScriptが41をリトルエンディアンで書く。Wasmが1を加えると同じ4バイトが42を表す。非共有メモリを1ページから2ページに拡張すると、古い固定長バッファは切り離され、新しいビューから既存の値を読める。" width="760" height="1040" loading="lazy"><figcaption>JavaScriptで書き込んだ値、Wasmによる更新、メモリを拡張した後のビューを順に確かめます。<a href="/study/images/browser/wasm-linear-memory-layout.svg" target="_blank" rel="noopener noreferrer">線形メモリとビューの図を拡大</a></figcaption></figure><p>4バイトを読むときは、先頭だけでなく最後のバイトまでメモリ内に入る必要があります。1ページが65,536バイトの例で、65,533から始めると末尾の65,536が範囲外です。この <code>i32.load</code> はトラップし、JavaScriptでは <code>WebAssembly.RuntimeError</code> が投げられます。ここで検査されるのは線形メモリ全体の境界です。その中に並べた配列や構造体ごとの境界は、言語処理系やプログラム側で扱います。<a href="https://webassembly.github.io/spec/core/exec/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのロード命令</a>、<a href="https://webassembly.github.io/spec/js-api/#error-objects" target="_blank" rel="noreferrer">JavaScript Interfaceのエラー型</a></p><h2 id="拡張した後はビューを作り直す" tabindex="-1">拡張した後はビューを作り直す <a class="header-anchor" href="#拡張した後はビューを作り直す" aria-label="Permalink to &quot;拡張した後はビューを作り直す&quot;">​</a></h2><p>今回のメモリは非共有で、1ページは64 KiB（65,536バイト）です。これはWasmでメモリを拡張する単位です。OSでのアドレス空間の予約や実メモリの確保方法は、エンジンの実装に依存します。<a href="https://webassembly.github.io/spec/core/exec/runtime.html#memory-instances" target="_blank" rel="noreferrer">WebAssembly Coreのメモリインスタンス</a></p><p>JavaScriptの <code>memory.grow(1)</code> は1ページを追加し、成功時には拡張前のページ数を返します。先にあったバイト列は保持され、追加した領域はゼロで初期化されます。既定の固定長バッファを使うこの例では、拡張に成功すると古い <code>ArrayBuffer</code> が切り離されます。そこから作った古い <code>Uint8Array</code> の <code>byteLength</code> は0になるので、読み書きするコードは新しい <code>memory.buffer</code> からビューを作ります。<a href="https://webassembly.github.io/spec/js-api/#memories" target="_blank" rel="noreferrer">JavaScript InterfaceのMemory</a></p><p>上限を超えるなど拡張できない場合、JavaScriptの <code>Memory.grow()</code> は <code>RangeError</code> を投げます。Wasm命令の <code>memory.grow</code> は失敗を <code>-1</code> で表します。Workerをまたいで共有するメモリでは <code>SharedArrayBuffer</code> と同期が関わるため、使うバッファの種類と実行環境を確認します。<a href="https://webassembly.github.io/spec/core/exec/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのmemory.grow</a>、<a href="https://webassembly.github.io/spec/js-api/#memories" target="_blank" rel="noreferrer">JavaScript InterfaceのMemory</a>、<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a></p><h2 id="ホストとの境界と、ゲームで使うとき" tabindex="-1">ホストとの境界と、ゲームで使うとき <a class="header-anchor" href="#ホストとの境界と、ゲームで使うとき" aria-label="Permalink to &quot;ホストとの境界と、ゲームで使うとき&quot;">​</a></h2><p>WasmからJavaScriptを呼びたい場合は、モジュールが関数をインポートとして宣言し、ページがインスタンス化の際に実装を渡します。たとえば表示処理やブラウザのAPI呼び出しをJavaScript側に置けます。Wasmの命令が読み書きできる範囲はメモリ命令の規則に従い、外の機能はホストが渡す実装を介して利用します。渡す関数にどの操作を許すかは、組み込む側で決めます。<a href="https://webassembly.github.io/spec/core/exec/runtime.html#function-instances" target="_blank" rel="noreferrer">WebAssembly Coreのホスト関数と実行環境</a>、<a href="https://webassembly.github.io/spec/js-api/" target="_blank" rel="noreferrer">JavaScript Interfaceのインポート</a></p><p>たとえばゲームの当たり判定やアセットのデコードをWasmにまとめ、入力、描画、音声などはページやツールチェーンの接続コードで扱う構成があります。C/C++ではEmscripten、Rustでは <code>wasm32-unknown-unknown</code> などがビルドの選択肢です。元のコードが使うファイルI/Oや描画APIをブラウザ向けに置き換える作業もあります。処理時間を見るときは、Wasm内の計算、JavaScriptとの呼び出し、データのコピーを別々に測ります。<a href="https://emscripten.org/docs/compiling/WebAssembly.html" target="_blank" rel="noreferrer">EmscriptenのWebAssembly向けビルド</a>、<a href="https://doc.rust-lang.org/rustc/platform-support/wasm32-unknown-unknown.html" target="_blank" rel="noreferrer">rustcのWebAssemblyターゲット</a>、<a href="/study/game/asset-loading.html">アセットロード</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>実践ページでは、WATと変換済みの <code>.wasm</code> を照らし合わせ、先頭8バイト、JavaScriptからの書き込み、Wasmの更新、拡張後のビュー、境界を越える読み取りを順に確認できます。<a href="/study/practice/browser/wasm-memory-observation.html">WebAssemblyと線形メモリの実験</a></p><p>配列や文字列を置く場所を確保し、ポインタと長さでWasmへ伝える方法は、<a href="/study/browser/wasm-data-and-allocation.html">WebAssemblyのデータ受け渡しとメモリ確保</a>で扱います。</p>',29)])])}const g=r(n,[["render",l]]);export{y as __pageData,g as default};
